/* ------------------------------------------------------------------ engine */
(function () {
  // Which slides this page shows. The SLIDES array above is always the whole
  // deck — the single source — and a host page narrows it by setting
  // window.DECK_FILTER before loading this file:
  //   "noquiz"  the talk, with the 55 multiple-choice slides left out
  //   "quiz"    only those, for the separate quiz handout
  // Anything else (or unset) shows everything. deck_to_pptx.py reads the
  // SLIDES array as text and never sees this, so it filters separately.
  const _isQuiz = (s) => /<ul class="quiz">/.test(s.html);
  const _f = (typeof window !== "undefined" && window.DECK_FILTER) || "all";
  const VIEW = _f === "quiz" ? SLIDES.filter(_isQuiz)
             : _f === "noquiz" ? SLIDES.filter((s) => !_isQuiz(s))
             : SLIDES;

  const deck = document.getElementById("deck");
  const bar = document.getElementById("progress-bar");
  const counter = document.getElementById("counter");
  const notesEl = document.createElement("div");
  notesEl.id = "notes";
  document.body.appendChild(notesEl);

  // build slides
  VIEW.forEach((s, i) => {
    const el = document.createElement("section");
    el.className = "slide" + (s.cls ? " " + s.cls : "");
    el.dataset.n = (i + 1);
    el.innerHTML = s.html;
    el.addEventListener("click", () => {
      if (document.body.classList.contains("overview")) { go(i); toggleOverview(false); }
    });
    deck.appendChild(el);
  });
  const slides = Array.from(document.querySelectorAll(".slide"));
  const N = slides.length;

  let cur = clampIndexFromHash();
  let notesOn = false;

  function clampIndexFromHash() {
    const h = parseInt((location.hash || "").replace("#", ""), 10);
    return isNaN(h) ? 0 : Math.max(0, Math.min(N - 1, h - 1));
  }

  // Draw each arrow in the active slide's diagrams, timed to its OWN length.
  // Every figure here is a flow, so the arrows drawing says "this way" without
  // narration. It has to be measured per element: the arrows range from 8px to
  // 334px, and one stroke-dasharray for all of them either hides the short ones
  // until the end or leaves a dash gap in the long ones.
  // Honour the machine's reduced-motion setting by default, but let the
  // presenter override it with "a". A laptop with Reduce Motion switched on
  // would otherwise silently disable a deliberate teaching animation, and the
  // speaker has no way to tell that is what happened.
  let motionOff = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  // Build each figure piece by piece: boxes and labels fade in along the flow,
  // then the arrows draw between them. A diagram that assembles is easier to
  // follow than one that lands complete — the eye is led rather than left to
  // search. Arrows are excluded here; they get the drawing treatment instead.
  // Put every figure into its finished state, immediately. CSS alone cannot do
  // this: the arrowhead is a presentation ATTRIBUTE (marker-end="url(#id)") and
  // the engine hides it with an inline style, which beats any print rule —
  // `marker-end: revert` reverts to the user-agent value, i.e. none, so the
  // handout printed every arrow as a headless line. Clearing the inline styles
  // is the only thing that gives the attribute back.
  function finaliseFigures() {
    document.querySelectorAll(".diagram svg *").forEach((n) => {
      n.style.transition = "none";
      n.style.opacity = "";
      n.style.transform = "";
      n.style.strokeDasharray = "";
      n.style.strokeDashoffset = "";
      n.style.markerEnd = "";
    });
  }
  window.addEventListener("beforeprint", finaliseFigures);
  // Headless printing does not always fire beforeprint; the media query does.
  const printMQ = window.matchMedia("print");
  if (printMQ.addEventListener) printMQ.addEventListener("change", (e) => { if (e.matches) finaliseFigures(); });

  function buildDiagram(slideEl) {
    if (motionOff) return;
    slideEl.querySelectorAll(".diagram svg").forEach((svg) => {
      const all = Array.from(svg.children).filter(
        (n) => !/^(defs|style|title|desc)$/i.test(n.tagName) && !n.hasAttribute("marker-end")
      );

      // Where is each part? Needed twice below, and getBBox is not free.
      const at = new Map();
      all.forEach((n) => {
        let b = { x: 0, y: 0 };
        try { b = n.getBBox(); } catch (e) { /* no geometry: treat as origin */ }
        at.set(n, b);
      });

      // The "you are here" chip strip sits along the top of every pattern
      // figure. It is navigation furniture, not content, and on a 36-part slide
      // it is 14 of the parts — animating it first spent nearly half the budget
      // before anything the audience came for appeared. It arrives at once.
      const strip = all.filter((n) => at.get(n).y < 40);
      const parts = all.filter((n) => at.get(n).y >= 40);
      strip.forEach((n) => { n.style.transition = "none"; n.style.opacity = "1"; n.style.transform = "none"; });

      // Build LEFT TO RIGHT, top to bottom within a column — not in document
      // order, and not in reading order either. Reading order sorts by row
      // first, which on the loop figure produced "The answer" (top right)
      // before "The model" (middle left): the picture assembled backwards
      // against its own arrows. Column-major matches the flow on the flow
      // diagrams, and on the before/after pairs it tells the story in order —
      // the whole "Without it" panel, then the whole "With it" panel.
      parts.sort((a, b) => {
        const A = at.get(a), B = at.get(b);
        const col = Math.round(A.x / 80) - Math.round(B.x / 80);
        return col !== 0 ? col : A.y - B.y;
      });

      parts.forEach((n, i) => {
        n.style.transition = "none";
        n.style.opacity = "0";
        n.style.transform = "translateY(10px) scale(.97)";
        n.style.transformOrigin = "center";
        void n.getBoundingClientRect();
        // Spread the stagger across a fixed budget rather than a fixed step:
        // a per-element delay makes a 43-part figure take three times as long
        // as a 13-part one, and the audience sits looking at an empty panel.
        const d = 0.10 + (i / Math.max(parts.length - 1, 1)) * 1.15;
        n.style.transition =
          "opacity .72s ease-out " + d + "s, transform .72s cubic-bezier(.2,.8,.3,1) " + d + "s";
        n.style.opacity = "1";
        n.style.transform = "none";
      });
    });
  }

  function drawArrows(slideEl) {
    if (motionOff) return;
    const arrows = slideEl.querySelectorAll(".diagram [marker-end]");
    arrows.forEach((p, i) => {
      let len;
      try { len = p.getTotalLength(); } catch (e) { return; }   // not a path/line
      if (!len || !isFinite(len)) return;
      // The last box lands at ~1.25s (0.10 base + 1.15 stagger + 0.72 fade), so
      // the first arrow leaves just after it — a line drawn between two boxes
      // that are still fading in reads as a glitch rather than a connection.
      const delay = 1.10 + Math.min(i, 8) * 0.17;
      const dur = 0.95;
      p.style.transition = "none";
      p.style.strokeDasharray = len;
      p.style.strokeDashoffset = len;
      p.style.opacity = "1";
      // Suppress only the HEAD while the line travels. An earlier version hid
      // the whole arrow until the draw was nearly over — which meant the line
      // drew underneath an invisible mask and the arrow simply popped in fully
      // formed. The drawing was real and nobody could see it.
      p.style.markerEnd = "none";
      void p.getBoundingClientRect();
      p.style.transition = "stroke-dashoffset " + dur + "s ease-out " + delay + "s";
      p.style.strokeDashoffset = "0";
      // Restore the head when THIS draw ends, not on a timer. A timer set on an
      // earlier visit to the slide fires during a later one and puts the head
      // back while the new line is still travelling — arrowheads floating at
      // their targets again, only intermittently, which is worse than always.
      if (p._headRestore) p.removeEventListener("transitionend", p._headRestore);
      p._headRestore = (ev) => {
        if (ev.propertyName !== "stroke-dashoffset") return;
        p.style.markerEnd = "";
        p.removeEventListener("transitionend", p._headRestore);
        p._headRestore = null;
      };
      p.addEventListener("transitionend", p._headRestore);
    });
  }

  let toastEl = null, toastTimer = null;
  function flash(msg) {
    if (!toastEl) {
      toastEl = document.createElement("div");
      toastEl.id = "toast";
      document.body.appendChild(toastEl);
    }
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove("show"), 1100);
  }

  function render() {
    slides.forEach((el, i) => el.classList.toggle("active", i === cur));
    buildDiagram(slides[cur]);
    drawArrows(slides[cur]);
    bar.style.width = (N > 1 ? (cur / (N - 1)) * 100 : 100) + "%";
    counter.textContent = (cur + 1) + " / " + N;
    const note = VIEW[cur].notes || "";
    notesEl.innerHTML = '<span class="lbl">Speaker notes — ' + (cur + 1) + "/" + N + "</span>" + note;
    if (history.replaceState) history.replaceState(null, "", "#" + (cur + 1));
    else location.hash = cur + 1;
  }

  function go(i) { cur = Math.max(0, Math.min(N - 1, i)); render(); }
  function next() { if (cur < N - 1) go(cur + 1); }
  function prev() { if (cur > 0) go(cur - 1); }

  function toggleOverview(force) {
    const on = force === undefined ? !document.body.classList.contains("overview") : force;
    document.body.classList.toggle("overview", on);
  }
  function toggleNotes() { notesOn = !notesOn; notesEl.classList.toggle("show", notesOn); }
  function toggleFullscreen() {
    if (!document.fullscreenElement) { (document.documentElement.requestFullscreen || function(){})(); }
    else if (document.exitFullscreen) { document.exitFullscreen(); }
  }

  // Recap interactions. Delegated, so slides built later still work, and kept
  // out of live.js because these need no Python runtime.
  deck.addEventListener("click", (e) => {
    const card = e.target.closest(".card.qa");
    if (card) { card.classList.toggle("open"); return; }
    const opt = e.target.closest(".quiz li");
    if (opt) {
      opt.closest(".quiz").classList.add("answered");
      opt.classList.add("picked");
    }
  });

  document.getElementById("next").addEventListener("click", next);
  document.getElementById("prev").addEventListener("click", prev);

  document.addEventListener("keydown", (e) => {
    switch (e.key) {
      case "ArrowRight": case " ": case "PageDown": case "l": case "j": next(); e.preventDefault(); break;
      case "ArrowLeft": case "PageUp": case "h": case "k": prev(); e.preventDefault(); break;
      case "Home": go(0); break;
      case "End": go(N - 1); break;
      case "o": case "Escape": toggleOverview(e.key === "Escape" ? false : undefined); break;
      case "s": case "n": toggleNotes(); break;
      case "f": toggleFullscreen(); break;
      case "a": {
        motionOff = !motionOff;
        if (motionOff) {
          // put everything back where it belongs, immediately
          document.querySelectorAll(".diagram svg *").forEach((n) => {
            n.style.transition = "none"; n.style.opacity = "1"; n.style.transform = "none";
            n.style.strokeDasharray = ""; n.style.strokeDashoffset = ""; n.style.opacity = "1";
          });
        } else {
          buildDiagram(slides[cur]); drawArrows(slides[cur]);
        }
        flash(motionOff ? "animation off" : "animation on");
        break;
      }
      default:
        if (/^[0-9]$/.test(e.key)) { const t = e.key === "0" ? 9 : parseInt(e.key, 10) - 1; if (t < N) go(t); }
    }
  });

  window.addEventListener("hashchange", () => { const i = clampIndexFromHash(); if (i !== cur) go(i); });

  render();
})();
